window.DRSTE_IMG={"accovacciato": "data:image/png;base64,", "aggancio": "data:image/png;base64,", "aterra": "data:image/png;base64,", "calcio": "data:image/png;base64,", "camminata1": "data:image/png;base64,", "camminata2": "data:image/png;base64,", "caricacalcio": "data:image/png;base64,", "caricapugno": "data:image/png;base64,", "colata": "data:image/png;base64,", "colpito": "data:image/png;base64,", "entrata": "data:image/png;base64,", "guardia": "data:image/png;base64,", "guardia2": "data:image/png;base64,", "ko": "data:image/png;base64,", "lancio": "data:image/png;base64,", "montante": "data:image/png;base64,", "nebbia": "data:image/png;base64,", "parata": "data:image/png;base64,", "paratabassa": "data:image/png;base64,", "pozza": "data:image/png;base64,", "presa": "data:image/png;base64,", "presa_debole": "data:image/png;base64,", "provetta": "data:image/png;base64,", "provettona": "data:image/png;base64,", "provocazione": "data:image/png;base64,", "pugno": "data:image/png;base64,", "rialzo": "data:image/png;base64,", "ritratto": "data:image/png;base64,", "salto": "data:image/png;base64,", "sconfitta": "data:image/png;base64,", "sgambetto": "data:image/png;base64,", "stordito": "data:image/png;base64,", "trasformazione": "data:image/png;base64,", "vittoria": "data:image/png;base64,"};window.DRSTE_SCR={"AGGANCIATO": "data:image/png;base64,", "BLUB": "data:image/png;base64,", "ELEMENTAVE": "data:image/png;base64,", "NEBBIA": "data:image/png;base64,", "TOMBINO": "data:image/png;base64,", "WHITECHAPEL": "data:image/png;base64,"};window.DRSTE_SRC="\nQUOTES.drste={intro:[\"Buonasera. Gvadisce un Negvoni vevde?\",\"Pevmetta: la sistemo col bastone.\",\"Londva, 1886. Si cominci.\",\"Un gentiluomo non alza mai la voce. Alza il bastone.\"],win:[\"ELEMENTAVE!\",\"Tutto in vegola, gentiluomo.\",\"Il Negvoni vevde ha fatto il suo dovere.\",\"PoVca tVoia... che seVata.\"],lose:[\"PoVca tVoia...\",\"Il Negvoni vevde... non ancova...\",\"AndVe, pensaci tu.\"]};\nCOUPLE.drste=COUPLE.drste||{}; COUPLE.drste.geme={intro:[\"Geme? Ho la stessa faccia. Ma la bombetta \u00e8 mia.\"],win:[\"NegVoni senza ghiaccio? Il mio \u00e8 vevde.\"],lose:[\"PoVca tVoia, fVatello.\"]};\nCOUPLE.geme=COUPLE.geme||{}; COUPLE.geme.drste={intro:[\"Chi \u00e8 questo con la mia faccia?\"],win:[\"Ti mangio il cuoVe. Anche a Londra.\"],lose:[\"PoVca tVoia, il NegVoni vevde...\"]};\nCOUPLE.drste.andre={intro:[\"AndVe... in questa stovia ci sei gi\u00e0 dentvo.\"],win:[\"L'F24 a Londva non vale.\"],lose:[\"Va bene: la cavvozza la paghi tu.\"]};\nCOUPLE.andre=COUPLE.andre||{}; COUPLE.andre.drste={intro:[\"Un dottore con la mia faccia? Fattura.\"],win:[\"Ravvedimento operoso, dottore.\"],lose:[\"VIULEEENZA... la sua.\"]};\nCOUPLE.drste.stefano={intro:[\"Avvocato, la sua avvinga \u00e8 finita. Ova pavla il dottove.\"],win:[\"Dottove batte avvocato.\"],lose:[\"Non ho altve domande.\"]};\nCOUPLE.stefano=COUPLE.stefano||{}; COUPLE.stefano.drste={intro:[\"Dottore, posi quella provetta.\"],win:[\"Corpo del reato: un Negroni verde.\"],lose:[\"Mi oppongo... alla nebbia.\"]};\nCOUPLE.drste.faja={intro:[\"Il Dio del Mare? A Londva piove e basta.\"],win:[\"Tvidente confiscato.\"],lose:[\"Mi sono bagnato la bombetta.\"]};\nif(SPRITES.drste){ const N=SPRITES.drste; N.lancio2=N.lancio; N.caricacalcio=N.caricacalcio||N.caricapugno; N.sguardo=N.provocazione; N.turbo=N.pugno; N.sfondamento=N.pugno; N.stordita=N.stordito; N.super1=N.nebbia; N.super2=N.nebbia; N.esulta1=N.vittoria; N.esulta2=N.vittoria; N.esulta3=N.vittoria; N.tifo=N.vittoria; N.volo=N.ko; N.svenuto0=N.aterra; N.vittoria2=N.trasformazione||N.vittoria; N.vittoria3=N.vittoria; }\n/* DRSTE1 - DR. STE: provetta di Negroni verde (distanza, BLUB!), aggancio col bastone (speciale), placcaggio (montante),\n   super \"Nebbia di Londra\" (tre colpi dalla nebbia). Evoluzione MR. ANDRE: tombino (distanza), carica a quattro zampe VIULEEENZA! (speciale),\n   artigliata (montante), super \"Carrozza di Whitechapel\" (carrozza nera con due zebre, si salta). */\nfunction drsteImg(n){ const D=window.DRSTE_IMG||{}, c=SPRITES.__dsImg=SPRITES.__dsImg||{}; if(!D[n]) return null; if(!c[n]){ const i=new Image(); i.src=D[n]; c[n]=i; } return c[n].complete&&c[n].width?c[n]:null; }\nfunction drsteFImg(n){ const T=((window.FORME_IMG||{}).drste_andre)||{}, c=SPRITES.__dsfImg=SPRITES.__dsfImg||{}; if(!T[n]) return null; if(!c[n]){ const i=new Image(); i.src=T[n]; c[n]=i; } return c[n].complete&&c[n].width?c[n]:null; }\nfunction drawDrsteProj(p){ let im, s=1, rot=0;\n  if(p.kind==='provetta'){ im=drsteImg('provetta'); s=0.42; rot=(G.frame%30)/30*Math.PI*2*(p.vx<0?-1:1); }\n  else if(p.kind==='tombino'){ im=drsteFImg('tombino'); s=0.62; rot=(G.frame%24)/24*Math.PI*2*(p.vx<0?-1:1); }\n  else if(p.dhook||p.dcar) return true;\n  if(!im) return false; ctx.save(); ctx.translate(p.x,p.y); ctx.scale(p.vx<0?-1:1,1); if(rot) ctx.rotate(rot); ctx.imageSmoothingEnabled=false; ctx.drawImage(im,-im.width*s/2,-im.height*s/2,im.width*s,im.height*s); ctx.restore(); return true; }\nconst DRSU={dmg:6,dmgE:18,alto:70,vel:22,rng:110}; try{ setTimeout(()=>{ ['provetta','nebbia','provettona','colata','pozza'].forEach(drsteImg); ['tombino','carrozza','negroni'].forEach(drsteFImg); },0); }catch(e){}\nfunction callDrste(f,o){ const ev=f.def.lv>=2;\n  if(ev){ const dir=f.facing||1; f.dsup={t:0,ev:1,dir:dir,cx:f.x-dir*700,tgt:o,hit:0}; floatText('WHITECHAPEL!',f.x,f.y-270,'#39ff14',24,60); try{ tone('sawtooth',80,500,.6,.09); }catch(e){} }\n  else { f.dsup={t:0,ev:0,tgt:o,hx:o?o.x:f.x+(f.facing||1)*220,n:0}; floatText('NEBBIA!',f.x,f.y-270,'#d8d8e0',24,60); try{ tone('triangle',140,60,.8,.08); }catch(e){} } }\nfunction stepDrste(f,o){ const a=f.atk;\n  if(a&&a.type==='sbuff'&&f.def.lv>=2&&a.m&&a.f>=a.m.s&&a.f<a.m.s+22){ const fwd=f.facing||1; f.x=Math.max(40,Math.min(W-40,f.x+fwd*9)); if(a.f%2===0) FX.push({x:f.x-fwd*50,y:f.y-8-rnd()*12,vx:-fwd*(1+rnd()*2),vy:-1-rnd()*2,life:16,c:rnd()<.5?'#6a5a4a':'#3a3a2a'}); }\n  const M=f.dsup; if(!M) return; M.t++; const t=o||M.tgt;\n  if(!M.ev){ if(t&&M.t<60) M.hx+=Math.max(-4,Math.min(4,t.x-M.hx));\n    if(M.t===22||M.t===40||M.t===58){ M.n++; if(t&&Math.abs(t.x-M.hx)<DRSU.rng&&t.state!=='ko'){ const last=M.n===3; hit(f,t,DRSU.dmg,last?14:8,last?40:20,{sup:true,heavy:last,launch:last,dirx:t.x>=f.x?1:-1,y:t.y-90}); G.shake=Math.max(G.shake,last?12:5); if(last&&t.state==='hit') floatText('SBAM!',t.x,t.y-230,'#ffffff',28,60); } }\n    if(M.t>84) f.dsup=null; return; }\n  if(M.t<12) return; M.cx+=M.dir*DRSU.vel; if(M.t%3===0) G.shake=Math.max(G.shake||0,3);\n  if(t&&!M.hit&&t.state!=='ko'&&Math.abs(t.x-M.cx)<90){ M.hit=1; if(t.y>GROUND-DRSU.alto){ G.shake=Math.max(G.shake,16); hit(f,t,DRSU.dmgE,14,46,{sup:true,low:true,heavy:true,launch:true,dirx:M.dir,y:t.y-60}); if(t.state==='hit') floatText('SBAM!',t.x,t.y-230,'#ffffff',30,60); } else M.salto=1; }\n  if(M.dir>0?M.cx>W+420:M.cx<-420){ f.dsup=null; } }\nfunction drawDrste(F){ if(!F||!F.def||F.def.spriteKey!=='drste') return; const M=F.dsup; if(!M) return; ctx.save(); ctx.imageSmoothingEnabled=false;\n  if(!M.ev){ const k=Math.min(1,M.t/14), out=M.t>70?Math.max(0,1-(M.t-70)/14):1;\n    for(let i=0;i<14;i++){ const ang=i*2.4+M.t*0.03, r=60+((i*37)%70), x=M.hx+Math.cos(ang)*r*1.4, y=GROUND-40-((i*53)%170)+Math.sin(ang+M.t*0.05)*10;\n      ctx.globalAlpha=0.32*k*out; ctx.fillStyle=i%3?'#c8c8d0':'#9a9aa8'; ctx.beginPath(); ctx.arc(x,y,46+((i*29)%30),0,Math.PI*2); ctx.fill(); }\n    if(M.t>18&&M.t<62&&(M.t%18)<6){ ctx.globalAlpha=0.9*out; ctx.strokeStyle='#1a1a1a'; ctx.lineWidth=7; const sx=M.hx+(((M.n%2)?-1:1)*40), sy=GROUND-150; ctx.beginPath(); ctx.moveTo(sx-60,sy-40); ctx.lineTo(sx+50,sy+50); ctx.stroke(); ctx.strokeStyle='#cfa84a'; ctx.lineWidth=3; ctx.stroke(); }\n    ctx.globalAlpha=1; ctx.restore(); return; }\n  if(M.t<12){ ctx.restore(); return; }\n  const car=drsteFImg('carrozza'); if(car){ const s=1.45, bob=((M.t>>2)%2)?2:0; ctx.translate(M.cx,GROUND+6-bob); ctx.scale(M.dir,1); ctx.drawImage(car,-car.width*s/2,-car.height*s,car.width*s,car.height*s); }\n  ctx.restore(); }\n\n/* DRSTE2 - speciale base: provetta gigante di Negroni senza ghiaccio rovesciata dall'alto sull'avversario */\nfunction drsteCascata(f){ const o=(G.f1===f)?G.f2:G.f1; f.dcasc={t:0,f0:G.frame,x:o?o.x:f.x+(f.facing||1)*220,tgt:o,hit:0}; try{ tone('triangle',300,90,.5,.08); }catch(e){} }\nfunction stepDrsteCasc(f){ const M=f.dcasc; if(!M) return; const nt=G.frame-M.f0; if(nt<=M.t) return; M.t=nt; const t=M.tgt;\n  if(t&&M.t<16) M.x+=Math.max(-7,Math.min(7,t.x-M.x));\n  if(M.t>=24&&M.t<=40&&!M.hit&&t&&t.state!=='ko'&&Math.abs(t.x-M.x)<100){ M.hit=1; G.shake=Math.max(G.shake,10); hit(f,t,13,12,34,{heavy:true,dirx:t.x>=f.x?1:-1,y:t.y-140}); if(t.state==='hit') floatText('NEGVONI!',t.x,t.y-230,'#ff3a2a',26,55); }\n  if(M.t>62) f.dcasc=null; }\nfunction drawDrsteCasc(F){ const M=F&&F.dcasc; if(!M) return; const pv=drsteImg('provettona'), co=drsteImg('colata'), pz=drsteImg('pozza'); ctx.save(); ctx.imageSmoothingEnabled=false;\n  const t=M.t, x=M.x, top=-40, inT=Math.min(1,t/12), out=t>52?Math.max(0,1-(t-52)/10):1; ctx.globalAlpha=out;\n  if(co&&t>=18&&t<=48){ const k=Math.min(1,(t-18)/8), h=(GROUND-60)*k, s=1.15; const w=co.width*s; ctx.drawImage(co,0,0,co.width,co.height*k,x-w/2,top+150,w,h); }\n  if(pz&&t>=24){ const s=0.9*Math.min(1,(t-24)/8+0.4); ctx.drawImage(pz,x-pz.width*s/2,GROUND+10-pz.height*s,pz.width*s,pz.height*s); }\n  if(pv){ const s=0.95, y=top-160+190*inT; ctx.translate(x-40,y+pv.height*s/2); ctx.rotate(Math.min(1,t/16)*0.9-0.2); ctx.drawImage(pv,-pv.width*s/2,-pv.height*s/2,pv.width*s,pv.height*s); }\n  ctx.restore(); }\n\n{ const _sd=stepDrste; stepDrste=function(f,o){ try{ stepDrsteCasc(f); }catch(e){} return _sd.apply(this,arguments); }; }\n{ const _dd=drawDrste; drawDrste=function(F){ try{ if(F&&F.def&&F.def.spriteKey==='drste') drawDrsteCasc(F); }catch(e){} return _dd.apply(this,arguments); }; }\n";